       id: _id('pre_'),
       meetingId: context.meeting.id,
       participantId: participantId,
       origin: 'manual',
       readAt: clock,
       recordedAt: clock,
       justification: justification,
       manualOrganizationId: _user(request)!.id,
     );
     attendances.add(attendance);
     _attendanceSequence++;
     _dirty = true;
     await _commit();
     return _json(request, 201, _attendanceJson(attendance));
   }

