+        body.containsKey('lidoEm') ? _parseOptionalDate(body['lidoEm']) : clock;
     if (readAt == null) return _error(request, 422, 'DADOS_INVALIDOS');
     if (body['lidoEm'] != null &&
         (readAt.isAfter(clock) ||
             clock.difference(readAt).abs() > const Duration(minutes: 10))) {
